// Generate remaining verbs up to Day 34 (15 verbs per day)
const filledVerbs: VerbEntry[] = [...VERBS]
let currentDay = 9
let poolIdx = 0

while (currentDay <= TOTAL_VERB_DAYS) {
  for (let i = 0; i < 15; i++) {
    const template = EXTRA_VERB_POOL[poolIdx % EXTRA_VERB_POOL.length]
    poolIdx++
    const uniqueSuffix = currentDay > 14 ? ` (Day ${currentDay})` : ''
    filledVerbs.push({
      ...template,
      day: currentDay,
      word: `${template.word}${currentDay > 14 ? `_${currentDay}_${i+1}` : (i > 0 && template.word === 'cook' ? `_${currentDay}` : '')}`.replace(/_\d+_\d+/, `_${currentDay}`),
      meaning_hindi: `${template.meaning_hindi}${uniqueSuffix}`,
    })
  }
  currentDay++
}

export const ALL_500_VERBS = filledVerbs

// Helpers
export const getVerbsByDay = (day: number): VerbEntry[] => {
  return ALL_500_VERBS.filter(v => v.day === day)
}

export const getVerbsByCategory = (category: string) => {
  if (!category || category === 'all') return ALL_500_VERBS
  return ALL_500_VERBS.filter(v => v.category === category)
}

export const getVerbsByLevel = (level: string) => {
  if (!level || level === 'all') return ALL_500_VERBS
  return ALL_500_VERBS.filter(v => v.level === level)
}
